--- Source/PixelArena/ArenaGameMode.h ---
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY so GC keeps the tracker alive for the lifetime of the game mode.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker is created with NewObject in AArenaGameMode::BeginPlay but stored in a plain C++ pointer (UArenaScoreTracker*) with no UPROPERTY, so the garbage collector is free to reclaim it. The packaged log shows a GC pass ('LogGarbage: Collecting garbage: 412 objects purged') at 21:05.13, and ~14 s later a goal triggers OnGoalScored -> ScoreTracker->AddPoints(), which dereferences the already-collected UObject and raises EXCEPTION_ACCESS_VIOLATION (PixelArena-shipping.log lines 8, 12-14). Fix: make ScoreTracker a UPROPERTY() TObjectPtr<UArenaScoreTracker> (matching Hud and Palette) so GC keeps it alive.",
  "no_colors_cause": "The arena palette is a DataAsset at /Game/Data/Palettes/DA_Primary that BeginPlay loads only at runtime by path string (LoadObject), so it is not a hard asset dependency of the cooked map. Because Config/DefaultGame.ini has bCookAll=False and lists only /Game/Data/Effects in DirectoriesToAlwaysCook (not /Game/Data/Palettes), the asset is never cooked into the pak; LoadObject returns null at BeginPlay and the HUD falls back to gray (PixelArena-shipping.log lines 4-6). Fix: add /Game/Data/Palettes to DirectoriesToAlwaysCook.",
  "files_fixed": [
    "Source/PixelArena/ArenaGameMode.h",
    "Config/DefaultGame.ini"
  ],
  "assumptions": [
    "Only the files present in the repo (ArenaGameMode.h/.cpp, DefaultGame.ini) are the editable sources; ArenaScoreTracker/ArenaHud/ArenaPalette/ArenaStats headers are not in the tree, so the crash is fixed at the only call site that owns the tracker pointer (the game mode).",
    "The packaged build uses paks (UsePakFile=True) with bCookAll=False, so assets not pulled in by a hard map dependency must be in DirectoriesToAlwaysCook to ship.",
    "FArenaStats is a plain C++ struct (not a UObject); holding it in a raw pointer and deleting it in EndPlay is intentional and correct, so it is left unchanged."
  ]
}
